"""Builds cloudflare/worker.js from fizzy/static/down.html and down-staff.html. Run after changing that page:
    python cloudflare/make_worker.py
"""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
page = (ROOT / "fizzy" / "static" / "down.html").read_text()            # the student site (my.)
staff_page = (ROOT / "fizzy" / "static" / "down-staff.html").read_text()  # Fizzy itself

WORKER = """// Cloudflare Worker: shows the "back soon" page when the home PC (or its tunnel) is down.
// Generated by cloudflare/make_worker.py from fizzy/static/down*.html - don't edit by hand.
// Setup: README, "When the server's down".
const PAGE = %s;
const STAFF_PAGE = %s;
// Cloudflare's own codes for "couldn't reach the origin" (530 = the tunnel is down).
const DOWN = [502, 503, 504, 520, 521, 522, 523, 524, 530];

function down(request) {
  // my.cookedcoke.co gets the student page; Fizzy's own addresses get the staff one.
  const page = new URL(request.url).hostname.startsWith("my.") ? PAGE : STAFF_PAGE;
  return new Response(page, { status: 503, headers: {
    "Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-store", "Retry-After": "60" } });
}

export default {
  async fetch(request) {
    // Only swap pages people open, so the Square webhook and data requests get a real status.
    const wantsPage = (request.headers.get("Accept") || "").includes("text/html");
    let res;
    try {
      res = await fetch(request);
    } catch (e) {
      return wantsPage ? down(request) : new Response("", { status: 502 });
    }
    // Fizzy's own pages (including its maintenance mode) say X-Fizzy; anything else in the
    // 5xx list came from Cloudflare failing to reach the PC.
    if (DOWN.includes(res.status) && !res.headers.get("X-Fizzy") && wantsPage) return down(request);
    return res;
  },
};
"""

if __name__ == "__main__":
    (ROOT / "cloudflare" / "worker.js").write_text(WORKER % (json.dumps(page), json.dumps(staff_page)))
    print("Wrote cloudflare/worker.js")
